def calculate_character_frequencies(text):
    """计算文本中每个字符的频率。"""
    frequencies = {}
    for char in text:
        frequencies[char] = frequencies.get(char, 0) + 1
    return frequencies

def compare_weighted_frequency_similarity(text1, text2):
    """基于字符频率的加权相似度计算。"""
    if not text1 or not text2:
        return 0
    freqs1 = calculate_character_frequencies(text1)
    freqs2 = calculate_character_frequencies(text2)
    weighted_intersection = sum(min(freqs1.get(char, 0), freqs2.get(char, 0)) for char in set(text1 + text2))
    weighted_union = sum(max(freqs1.get(char, 0), freqs2.get(char, 0)) for char in set(text1 + text2))
    return weighted_intersection / weighted_union if weighted_union > 0 else 0

def calculate_edit_distance_similarity(text1, text2):
    """基于编辑距离的相似度计算。"""
    m, n = len(text1), len(text2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            elif text1[i-1] == text2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
    return 1 - dp[m][n] / max(m, n) if max(m, n) > 0 else 0

def compare_similarity(text1, text2):
    """计算两个字符串之间的相似度（基于字符集合的交集和并集）。"""
    if not text1 or not text2:
        return 0
    intersection = len(set(text1) & set(text2))
    union = len(set(text1) | set(text2))
    return intersection / union if union > 0 else 0

def find_match_with_similarity_method(input_text, corpus, similarity_method, similarity_threshold):
    highest_similarity = 0
    closest_match_group = None

    for question_group in corpus.keys():
        for question in question_group:
            similarity = similarity_method(input_text, question)
            if similarity > highest_similarity and similarity > similarity_threshold:
                highest_similarity = similarity
                closest_match_group = question_group

    return closest_match_group, highest_similarity

def find_closest_match(input_text, corpus, similarity_threshold=0.48):
    """找到最接近的匹配项。"""
    similarity_methods = [
        calculate_edit_distance_similarity,
        compare_weighted_frequency_similarity,
        lambda text1, text2: (compare_weighted_frequency_similarity(text1, text2) +
                              calculate_edit_distance_similarity(text1, text2) +
                              compare_similarity(text1, text2)) / 3,
        compare_similarity
    ]

    for method in similarity_methods:
        match, similarity = find_match_with_similarity_method(input_text, corpus, method, similarity_threshold)
        if similarity > similarity_threshold:
            return match

    return None


def compare_sentence_similarity(sentence1, sentence2):
    """计算两个句子的相似度"""
    words1 = set(sentence1.split())
    words2 = set(sentence2.split())
    return len(words1.intersection(words2)) / max(len(words1), len(words2))
    
def add_emotion(text):
    emotions = ["😊", "🙏", "😃", "😜", "😎", "👍", "💖","😊","😚","😉","😳","😇","😁","🙂","🎉","🌹","🌷","🌈","🌟","💓","💗","😄","✨","✌️","👏","😺"]
    no_emotion_triggers = ["呆", "傻", "不聪明", "主人"]

    # 检查文本中是否包含了上述关键词
    if not any(trigger in text for trigger in no_emotion_triggers):
        if random.random() < 0.28:
            text += " " + random.choice(emotions)
    
    return text
    
def type_like_human(text, delay=0.03):
    for char in text:
        sys.stdout.write(char)
        sys.stdout.flush()
        time.sleep(random.uniform(0.026, 0.03))
    print()
    print()

