def check_idiom(input_text):
    # 如果输入文本超过一定字符数，可选择返回None或继续搜寻成语
    if len(input_text) > 20:
        return None

    found_idioms = []
    for idiom in idioms:
        if idiom in input_text:
            found_idioms.append(f"{idiom}的意思是：{idioms[idiom]}")

    if found_idioms:
        return '\n'.join(found_idioms)  # 使用换行符连接每个成语的解释
    return None

def convert_chinese_to_arithmetic(expression):
    # 中文数字到阿拉伯数字的映射
    chinese_to_arabic = {'一': '1', '二': '2', '两': '2', '三': '3', '四': '4', '五': '5', '六': '6', '七': '7', '八': '8', '九': '9', '零': '0'}
    
    # 中文计算符号到阿拉伯符号的映射
    chinese_to_symbol = {'加': '+', '减': '-', '乘': '*', '除': '/', '×': '*', '÷': '/'}

    # 替换中文数字和符号
    for chinese, arabic in chinese_to_arabic.items():
        expression = expression.replace(chinese, arabic)
    for chinese, symbol in chinese_to_symbol.items():
        expression = expression.replace(chinese, symbol)

    return expression

def contains_operators(expression):
    # 检查是否包含中文或阿拉伯运算符
    chinese_operators = ['加', '减', '乘', '除']
    arabic_operators = ['+', '-', '*', '/']
    return any(op in expression for op in chinese_operators) or re.search(r'[\+\-\*\/]', expression)

def handle_math_operations(input_text):
    # 将中文表达式转换为阿拉伯数字和计算符号
    converted_input = convert_chinese_to_arithmetic(input_text)

    # 检查表达式中是否包含运算符
    if contains_operators(input_text):
        try:
            # 直接计算表达式的结果
            result = eval(converted_input)
            return f"等于 {result}"
        except Exception as e:
            return "计算错误: " + str(e)
    
def get_current_time():
    """ 获取当前时间 """
    return datetime.now().strftime("现在是%H点%M分%S秒")

def get_current_date():
    """ 获取当前日期 """
    return datetime.now().strftime("今天是%Y年%m月%d日")

def get_week_day():
    """ 获取当前星期 """
    week_days = ["星期一", "星期二", "星期三", "星期四", "星期五", "星期六", "星期日"]
    today_week_day = week_days[datetime.now().weekday()]
    return f"今天是{today_week_day}"

