def get_current_weather():
    month = datetime.now().month
    weather_advice = {
        "春天": ["我不能访问有关天气的回复，不过我可以告诉你这个季节的温度范围是5℃ ~ 20℃。昼夜温差大，注意增减衣物。☀️","春季一般表现为气温逐渐升高，但早晚仍然较凉，平均气温大约为5℃ ~ 20℃。此时期可能会有春雨，适量雨水有利于植物生长。春天的风较大，这也是春季特有的天气现象之一。除了温和的气温，可能还会遇到几天春寒料峭，请注意适时调整穿着。"],
        "夏天": ["我无法回答关于天气的具体内容。我只知道现在天气炎热，应该注意防晒和补水。当前月份的温度为25℃ ~ 35℃。","夏季通常气温较高，有时会有热浪发生，平均气温在25℃ ~ 35℃之间。高温天气需要注意防暑降温，并且防止中暑。夏日经常会有雷阵雨，天气多变，下午和傍晚可能会遇到短暂的强降雨，出行时请携带雨具，注意防雷避雨。"],
        "秋天": ["抱歉，我还不知道天气活动。不过根据当前月份来判断，温度会逐渐下降，气温可能是10℃ ~ 25℃。可以适当增加衣物。","秋季气温适宜，平均气温为10℃ ~ 25℃。此时气候干燥，少雨，早晚温差较大，适宜户外运动和观赏秋叶。秋天时，可以感受到清凉的天气和宜人的温度，但也要注意干燥带来的喉咙不适或皮肤干燥问题。"],
        "冬天": ["作为一个文本模型，我没有实时的气象信息，建议查看最新的天气预报。现在气温寒冷，可能会下雪，温度在-5℃ ~ 10℃。北方地区可能会下降至零下30度左右。注意保暖。❄️","冬季寒冷，气温可能低至-15℃，高温通常不超过10℃。注意穿着保暖的衣物，尤其是在雪天或刮大风的时候。冬季可能伴有降雪或冰冻，雪后景色宜人，但同时路面滑，出行时要谨慎。低温也可能导致水管冻裂，需做好防寒措施。"]
    }

    if month in [3, 4, 5]:
        weather = "春天"
    elif month in [6, 7, 8]:
        weather = "夏天"
    elif month in [9, 10, 11]:
        weather = "秋天"
    else:
        weather = "冬天"

    advice = random.choice(weather_advice[weather])
    return f"我不能访问有关天气的信息，不过现在是{weather}。{advice}"

def generate_story():
    """ 生成详细的故事 """
    stories = [
        ("好的，让我为你生成一篇故事。\n\n从前有座山，山里有座庙，庙里有个老和尚和一个小和尚。老和尚对小和尚讲故事：\n"
         "   在很久很久以前，有一个名叫艾瑟斯的勇敢骑士，他为了拯救被邪恶巫师莫戈斯囚禁的公主莉娅，踏上了漫长的旅途。\n"
         "   艾瑟斯穿越了黑暗森林，跨过了沼泽地，攀登了险峻的山峰，最终来到了莫戈斯的堡垒——黑暗塔。\n"
         "   在一场激烈的战斗中，艾瑟斯凭借着智慧和勇气，打败了莫戈斯，解救了公主莉娅。\n"
         "   公主莉娅感激艾瑟斯的救命之恩，他们决定一起回到公主的王国，并举行了盛大的婚礼。\n"
         "   从此，他们幸福地生活在一起，成为了民间传颂的英雄。然而，故事并没有结束。\n"
         "   多年后，一个新的邪恶势力崛起，艾瑟斯和莉娅的子女们也将踏上属于自己的冒险之旅。\n"
         "   他们是否能够继承父母的勇敢和智慧，战胜新的敌人，保卫王国呢？"),
         
         ("从前有一个古老的村落，被高高的山峦所环抱，那里有一座传说中的水晶湖，据说湖中住着一位拥有预知未来能力的湖神。\n"
         "   一天，村子里莱斯顿老人做了一个奇怪的梦，梦见湖神告诉他，只有找到遗失在无尽密林深处的神秘宝石，才能化解即将到来的灾难。\n"
         "   责任感十足的少年艾登，毅然决然地踏上了寻找神秘宝石的征程。艾登首先来到了智者威晤的家，智者威晤是一个饱读诗书的独居老人，他给艾登提供了密林的地图和一把可以指示方向的魔法罗盘。\n"
         "   带着智者的祝福，艾登跨过险象环生的蛇蝎岭，与狼群斗智，又智破了捕猎者的陷阱。经过重重困难，终于来到了湖神所说的密林深处。\n"
         "   他发现宝石被放在一个被光环环绕的祭台上，但它被兽人部落首领——扎尔加所守护。艾登想出了一个计划，他利用自己制作的小鸟假饵引开兽人，然后瞬间抢走宝石。\n"
         "   当艾登回到村子，他所持的宝石突然亮起强烈的光芒，驱散了一直笼罩在村落上空的黑暗云层。原来，这片云层中孕育的是一个古老的灾难，它可以摧毁一切。\n"
         "   人们欢呼艾登的英勇与睿智，他的故事成为了村中流传百年的传说。而那神秘宝石，则被安置在村子中心的广场上，作为保护村子的永恒象征。\n"
         "   而就在许多年后，一位旅者遇到了梦境中的湖神，湖神告诉了旅者一个秘密——宝石中还封印着一段未知的往事和对未来的预言……"),
        
    ]
    return random.choice(stories)
    
def generate_ghost_story():
    """ 生成详细的鬼故事 """
    ghost_stories = [
        ("下面是你要的鬼故事：👻\n\n在一个偏远的山村，有一座荒废的宅子，传说那里住着一个复仇的鬼魂。\n"
         "   据说，这个鬼魂是一位被冤枉而死的富翁的灵魂。他死前发誓，如果他的冤屈无法得到伸张，他的鬼魂将永远游荡在宅子中。\n"
         "   每当夜幕降临，宅子里便会传出奇怪的声音，像是有人在低语，又像是物品在移动。\n"
         "   一个勇敢的记者听说了这个故事，决定去宅子一探究竟。\n"
         "   他进入宅子后，感受到了一种压抑的氛围，仿佛有什么东西在监视着他。\n"
         "   他开始调查富翁的死亡真相，最终发现了一个隐藏多年的阴谋。\n"
         "   在揭露真相的过程中，他意外地帮助了富翁的鬼魂，使其得以安息。\n"
         "   从那以后，宅子里的怪声消失了，取而代之的是一种平和的气息。"),
         
         ("在一个古老的村庄里，有一座被遗弃的庄园，传说那里住着一个忧伤的鬼魂。\n"
         "   据说，这个鬼魂是一位年轻的女子的灵魂，她在很多年前因一场悲剧而失去了生命。\n"
         "   每当月圆之夜，她的鬼魂会在庄园里游荡，哭泣和叹息，寻找着解脱和安息。\n"
         "   有一天，一个好奇的旅行者听说了这个故事，决定在月圆之夜去庄园探险。\n"
         "   当他进入庄园时，他感受到了一种冰冷的气氛，仿佛有什么东西在注视着他。\n"
         "   他继续深入，发现了女子的鬼魂，她看起来如此真实，却又是那么虚幻。\n"
         "   女子的鬼魂向旅行者诉说了她的故事，请求他的帮助来解开她的诅咒。\n"
         "   旅行者决定帮助她，他们一起揭开了一场古老的秘密，最终使女子的鬼魂得到了解脱。\n"
         "   从那以后，庄园里的哭泣声消失了，取而代之的是一种宁静和平和的气氛。💀"),
        
       
    ]
    return random.choice(ghost_stories)

