def generate_novel():
    """ 生成详细的小说 """
    novels = [
        ("没问题，以下是我写的小说。\n\n在遥远的未来，地球已经变成了科技的天堂，但在这繁华的背后，却隐藏着不为人知的秘密。一位名叫艾伦·斯图尔特的年轻科学家，在一次偶然的实验中，发现了一项惊人的技术——时空穿梭。\n"
         "   这项技术有着改变人类命运的力量。艾伦意识到，这项技术如果落入错误的手中，可能会导致灾难性的后果。\n"
         "   于是，他决定踏上揭露真相的旅程。在途中，他遇到了来自不同领域的朋友，他们一起面对了来自强大势力的追捕和攻击。\n"
         "   艾伦和他的朋友们在旅途中逐渐揭开了时空穿梭技术的神秘面纱，同时也发现了隐藏在地球联盟政府内部的阴谋。\n"
         "   他们是否能够成功揭露真相，拯救人类免于灾难呢？这场冒险才刚刚开始。然而，他们并没有意识到，这场冒险将带领他们走向一个他们从未想过的地方——平行宇宙。\n"
         "   在平行宇宙中，他们发现了另一个版本的地球，一个科技与魔法并存的世界。在这个世界中，艾伦和他的朋友们将面临更加艰巨的挑战。\n"
         "   他们是否能够适应这个新世界，找到回到原来地球的方法，同时阻止邪恶势力毁灭两个世界的阴谋呢？这一切都将在这个史诗般的冒险中揭晓。"),
         
         ("好的，我为你写篇小说。\n\n在不远的将来，一个名为诺瓦莉雅的星球上，人与机器人共同构建了一个看似平衡的社会。在这里，高耸的摩天大楼触碰云端，飞行汽车穿梭于天际，而每个人的命运都似乎被精密的算法所预定。\n"
         "   在诺瓦莉雅的最高科学院中，年轻而聪明的女研究员艾莉森·薇阿，偶然发现了一种可以操控心智的危险技术——'心灵钥匙'。\n"
         "   随着艾莉森对这项禁忌技术的研究深入，她开始怀疑政府的最高太守们早已利用此项科技操控人民，维护他们的统治。\n"
         "   心灵钥匙的存在牵动了抵抗组织的注意。一名神秘的革命将领卡拉·雷瑟出现在艾莉森的生活中，告诉她，星球的未来掌握在她的手中。两人联手，开始了一场颠覆整个社会结构的生死斗争。\n"
         "   他们踏上了揭露真相的冒险之旅，从地下反抗城市的暗谷，到浮游的科技园区，再到广袤的外星人殖民地。在这漫长的反抗道路上，艾莉森不断地被迫质疑自己的信仰、自由，乃至人性的本质。\n"
         "   他们意识到，心灵钥匙只是科学院巨大秘密中的冰山一角。它背后隐藏的真相，不仅关系到卡拉与艾莉森的命运，还有可能撼动整个宇宙的力量平衡。\n"
         "   就在艾莉森和卡拉准备揭开所有谜团之际，一股既熟悉又陌生的力量悄悄觉醒。原来，艾莉森自身就隐藏着改变一切的关键，而这个秘密，甚至连她自己都未曾觉察。\n"
         "   两位女性的命运交织在一起，展开了一场时空跨度的史诗冒险，揭示了一个超越科学与魔法，关乎宇宙命运的浩大谜团。\n"
         "   而等待他们的，则是一场前所未有的危机。一个叹息于宇宙深处，眼观星辰兴亡的存在即将醒来，它的眼目，已经锁定了诺瓦莉雅。\n"
         "   在这不可预知的宇宙风暴中，艾莉森与卡拉将如何选择，以及他们又将如何面对自己内心的阴暗面，这一切构成了本小说绵延不断的紧张和悬疑……"),
        
    ]
    return random.choice(novels)
    
def generate_fantasy_novel():
    """生成玄幻小说模板"""
    novels = [
        ("以下是你要的玄幻小说。\n\n在一个古老的世界中，存在一个被遗忘的王国，名为艾瑟兰。在艾瑟兰，魔法与剑术是荣耀的象征，而龙和其他神秘生物则在这片大陆上肆意游荡。\n"
         "   在王国的边际小镇，一个年轻的剑士亚当发现自己拥有召唤和驯服龙的罕见能力。但正当他开始掌握这份力量时，一股邪恶的暗影力量开始在艾瑟兰蔓延，它试图复活一个古老的恶龙，威胁整个王国的安宁。\n"
         "   亚当必须前往艾瑟兰遗忘之境，寻找传说中的灵魂宝石，才有可能阻止邪恶势力的计划。途中，他结识了勇敢的魔法师莉娜和精灵射手艾尔文，一同踏上旅程。\n"
         "   他们在险恶的怪物，诡谲的迷雾森林和不断变幻的魔法迷宫中历经重重考验，终于找到了宝石的线索。但艾瑟兰的暗黑势力也在默默观察着他们的一举一动，并派出了强大的手下阻挠他们。\n"
         "   旅程中，亚当与他的同伴们揭开了一个个古老的秘密和谎言，也面对着自身的恐惧与困惑，他们之间的友谊与信任受到了前所未有的考验。\n"
         "   但王国的命运摆在他们面前，亚当必须在决战之时挺身而出，用他的力量证明自己是真正的龙之使者。\n"
         "   在绝望中寻找希望，在黑暗对抗中发现光明，亚当和他的朋友们的冒险才刚开始，而他们即将面对的，则可能是比恶龙更为可怕的敌人......"),
         
         ("以下是一篇玄幻小说：\n\n在神秘莫测的大陆，古老的族群和强大的兽类共存，一种名为灵气的力量覆盖了整个世界。在这个世界中，一位名叫萧云的年轻少年，自小因体内封印了一只上古神兽而被族人排斥。\n"
         "   在一次意外之中，萧云觉醒了体内的神兽，并得知自己拥有改变命运的力量。他决定离开自己的部落，踏上修炼之路，寻找解开体内封印的方法。\n"
         "   在广阔的大陆上，萧云经历了种种磨难和考验，结识了志同道合的伙伴，共同成长，一步步揭开了隐藏在大陆深处的秘密。\n"
         "   他们的旅途中，发现了古老的遗迹，异族入侵的危机，甚至是渡劫成仙的奥妙。萧云和他的伙伴们将面对怎样的挑战，他们又能否阻止即将到来的灾难？\n"
         "   在这个充满魔法和剑术的世界里，秩序与混沌争斗，光明与黑暗并存，萧云必须找到内心的真实和力量，才能揭开命运的真相。"),
    ]
    
    return random.choice(novels)
    
def generate_romance_novel():
    """生成言情小说模板"""
    novels = [
        ("以下是一个言情小说供你参考。\n\n在波希米亚风格的小镇上，名为莫妮卡的年轻画家，在开放的市集摆摊卖画。她的画作充满了梦境般的色彩，但生活中的莫妮卡却总是感到孤独。\n"
         "   一日清晨，一位神秘的买家对她的画作赞不绝口，那是个英俊而深情的诗人——埃文。埃文对莫妮卡的画有着深深的理解，他的出现逐渐让莫妮卡的世界变得丰富多彩。\n"
         "   两人在艺术的载体上产生了共鸣，而莫妮卡发现，与埃文的邂逅似乎是命运的安排。随着时间的推移，从欣赏到依赖，再到心动，爱情在不经意间绽放。\n"
         "   但莫妮卡不知道的是，埃文背后有一个无法言说的秘密，这个秘密不仅可能摧毁他们的爱情，还可能撼动整个艺术圈。\n"
         "   当真相浮出水面时，莫妮卡必须做出选择——是守护她的爱情，还是守住她的理想与个人信念。\n"
         "   在这段扣人心弦的浪漫故事中，莫妮卡和埃文的每一个选择都充满了爱与牺牲的考验，而他们的故事也将成为永恒的画作中最动人的一笔。"),
         
         ("柔和的月光洒在安静的海滨小镇，恬淡的浪花轻抚着细沙，每一次回响都像是在诉说着未尽的故事。艾莉森站在翡翠色的海岸边，手中紧握着一封泛黄的老信，那是来自初恋维克托的最后一份信件。\n"
         "   曾经的他们，像是海边轻盈的风筝和细长的线，总以为会被命运紧紧相连。维克托的温柔眼眸和鼓励的话语，总在艾莉森遇到困惑时涌现在心头，给予她勇气。但突如其来的分离，就像暴风雨中断裂的线，让他们的爱随风远去。\n"
         "   现在的艾莉森，明白那份爱早已随风逝去，但维克托的影子仍旧是她内心深处最柔软的部分。她天真地希望，旧爱能随着信件的字迹重现，温暖她沧桑的心。\n"
         "   就在艾莉森再次准备将心海埋藏的时候，维克托却意外出现在了小镇。那个她深爱着的男人，带着更加成熟稳重的神态，和编织着赎罪的话语。他解释了当年的离去，原来是一场误会，是他愚蠢的决定所带来的遗憾。\n"
         "   眼前的他，仿佛依旧是那个最熟悉的陌生人。艾莉森的心，如同被触电般颤抖，她怎能忘记那些年他们共同铸造的甜蜜回忆？怎能忘记那些夜晚他们相互倾诉的温暖话语？但同时，这些年波折的揉磨又如刀割一般，让她害怕再次打开心扉。\n"
         "   纠结的心情像海中的浪潮，忽而澎湃，忽而宁静。艾莉森必须在过往的爱与新的未来之间做出选择，而每一个决定都如同在月光下跳动的音符，编织成一首关于爱与自我救赎的挽歌。\n"
         "   这部言情小说深刻地描绘了第二次爱情的复杂与美丽，探究了人心中关于原谅、成长和重新开始的微妙情感，展现了爱情中最纯粹但也最复杂的层面。"),
         
         ("在巴黎铁塔下，艾琳娜穿着她最美的裙子，等待着她一生中最重要的约会。她的心跳得如此之快，仿佛下一秒就要跳出来。她辗转于巴黎的蜿蜒小路和浪漫街角，一直在梦想着这一天的到来，直到她遇见了安德烈。\n"
         "   安德烈是一位魅力四射的艺术家，他的画作就像他的眼睛一样，总能深深吸引着艾琳娜。他们的相遇像是冥冥中自有安排，当他们的手指在蒙马特的画布上轻轻相触，两人的灵魂就在那一瞬间交汇。\n"
         "   艾琳娜被安德烈的才华和热情深深吸引，而安德烈也为艾琳娜的美丽与智慧所折服。他们一起度过了许多个金色午后和星光灿烂的夜晚，分享着彼此对生活和艺术的热爱。\n"
         "   但生活不如艾琳娜笔下的小说那般完美。安德烈的过去如同他的画一般复杂，他的生活中充满了不为人知的阴影。当艾琳娜逐渐揭开安德烈神秘面纱的同时，她也被卷入了一场激烈的情感与道德的冲突之中。\n"
         "   面对未来的种种不确定，艾琳娜不知道她是否应该继续沿着这条充满未知的道路走下去。安德烈会选择抛开一切追随她吗？还是两人终将成为夜空中悲伤而遥远的星?\n"
         "   在这个世界上最浪漫的城市中，艾琳娜和安德烈的故事如同一幅未完成的画作，等待着最后的一笔。而他们的爱情，或将开出最美的花，或将留下最苦的泪。")
       
    ]
    return random.choice(novels)
    
def generate_scifi_novel():
    """生成科幻小说模板"""
    novels = [
        ("生成一篇科幻小说：\n\n在遥远的未来，人类在银河系的一颗名为阿耳忒弥斯的星球上建立了新的文明。科技的发展使得人类寿命延长，人工智能与每个人的日常生活密不可分。\n"
         "   然而，在阿耳忒弥斯的地下深处，一个古老的秘密正等待被发现。一个年轻的天文学家莱拉，在追踪一颗神秘的暗物质脉冲信号时，偶然揭开了这个秘密。它关乎到了星球的未来和人类的起源。\n"
         "   莱拉的发现引起了统治者的警觉，一场关乎真相的斗争随之展开。莱拉不得不和来自各方的盟友一起，对抗强大的执政团体，揭示科技幕后隐藏的黑暗面。\n"
         "   一场惊心动魄的太空之旅即将开始，权力的游戏和知识的力量在浩瀚的宇宙中碰撞，一个伟大的秘密即将震惊全银河系。\n"
         "   这部科幻小说将带领读者进入宏大的银河系纪元，探讨科技发展与人性的深层次关系，描绘一个充满奇迹及危险的未来世界。"),
         
         ("在宇宙中心的星际交错点，一个被遗忘的古老空间站对所有迷失的旅者敞开了大门。希娜，一个拥有异能的机械师，在这个无人知晓的岛屿上寻求着自己的过去。\n"
         "   这座空间站充满了来自各个世界的流浪者、大冒险家，以及那些对旧世界无限怀念的灵魂。他们在这里交换着信息，分享着故事，一起揭露着宇宙的秘密和可能性。\n"
         "   希娜发现，空间站的运转并不正常，似乎有个更深层次的力量在操纵着一切。在一群异类中，她遇到了她真正的同盟，一个阴谋，一个可能颠覆宇宙秩序的真相，正在逐渐浮出水面。\n"
         "   她必须用自己的智慧和勇气，解决每个难题，拼凑起记忆中的碎片，以面对即将到来的挑战。而在这充满未知的旅途中，她发现了自己真实的力量和命运的召唤。\n"
         "   在这部迷人的科幻小说中，读者将随希娜一起解锁宇宙最深处的秘密，见证一个普普通通的个体如何在星辰舞台上发现自己的价值，并影响整个银河系的命运。"),

        ("当最后一缕阳光逃逸出超新星爆炸的包围圈，人类的避难所——'乌托邦星极'迎来了新的希望之光。赛博人类与生物机械种族的紧张关系正在这颗宜居星球上逐渐浮出水面。\n"
         "   克拉拉，一名心灵强大的心理导师，试图在这两个种族之间建立和平。她深知，若是冲突爆发，将无一人能从中全身而退。\n"
         "   在处理种族间的外交谈判时，克拉拉意外发现了一个关于星极存在之秘的惊天阴谋。她的行动吸引了一位神秘组织的注意，他们希望用克拉拉的能力来实现他们不可告人的计划。\n"
         "   为了保护自己的生命与星极的未来，克拉拉不得不巧妙地在政治漩涡中航行，同时寻找可以揭示真相的关键。\n"
         "   在这条波云诡谲的道路上，克拉拉将面临关乎生命意义和智慧生命发展方向的根本问题。这部科幻小说不但扣人心弦，更是对人类潜力无限探索的一次绝佳冒险。"),
         
    ]
    return random.choice(novels)
    
def generate_mystery_novel():
    """生成悬疑小说模板"""
    novels = [
        ("悬疑小说：\n\n在一个阴雨连绵的夜晚，著名侦探艾丽卡收到了一个神秘的电话，邀请她前往远离喧嚣的古堡解开一桩悬案。\n"
         "   她踏上了前往古堡的路途，在古堡的大门迎接她的，是一对显得有些紧张的老管家和主人。主人声称在一个雷雨交加的夜晚，他听到了庄园上方山林中传来的一声尖叫，随后便发现身份不明的女子在他们的家族墓地中惨死。\n"
         "   身为家族的守护者，而又无法解释此事，主人希望艾丽卡能够帮他们洗清嫌疑。\n"
         "   在调查过程中，艾丽卡逐渐发现这件案件似乎与家族的古老传说有所关联，那是一个关于诅咒与宝藏的故事，每一代的继承人都被祖先的错误所累及。\n"
         "   当艾丽卡越来越接近真相时，她发现自己已经置身于一个复杂的阴谋之中。真相很快将被揭开，而每一个人的命运也将因此改变。\n"
         "   这是一场与时间的赛跑，而在这场探寻真相的过程中，每个人都可能成为下一个受害者。"),
         
         ("厄运笼罩的小镇突然举办了一场盛大的节日庆典，居民们带上面具，仿佛要将一切阴霾一笑而过。然而就在庆典的高潮，镇上的名人汉纳失踪了。\n"
         "   退休侦探艾米利亚，凭借着自己多年积累的直觉，感觉到这背后隐藏着令人不安的真相。在寻找汉纳的过程中，她发现每个人的面具后都藏着不可告人的秘密。\n"
         "   通过一系列精心设计的调查，艾米利亚一步步揭露了小镇上的历史血案，一个关于贪婪、复仇和救赎的故事悄然展开。\n"
         "   真相总是残酷的，而在这场危险的游戏中，侦探艾米利亚必须用自己的智慧和决心，揭开汉纳失踪案背后最大的谜团。\n"
         "   这是一本融合了深刻人性探讨和悬疑元素的小说，每个角色的命运都交织在一起，构成了一张大网，而当艾米利亚接近中心时，她也将面临一个意想不到的选择。"),
         
    ]
    return random.choice(novels)

