def generate_letter():
    """ 生成个人信件模板 """
    letters = [
        ("亲爱的{name}，\n"
         "    希望这封信能在你最需要的时候抵达。现在我在{place}，每当看到{scene}，都会想起和你共度的时光。\n"
         "    我想告诉你{message}。\n",
         "    无论距离多远，你始终在我的心中，希望不久的将来我们能再次相聚。\n"
         "    此致\n"
         "    敬礼，\n"
         "{sender_name}\n"),
        ("尊敬的{title}{last_name}，\n"
         "    很荣幸能有机会通过这封信与您交流。自从上次会面以来，我一直在思考{topic}的问题，并有了一些新的见解。\n"
         "    我希望能有机会与您进一步探讨，看看是否有合作的可能性。\n"
         "    请您在方便的时候告知，我们是否能约个时间见面或是通过电话会议来讨论。\n"
         "    期待您的回复，并祝愿一切顺利。\n"
         "    真诚的，\n日期"),
        
        ("亲爱的{name}，\n\n"
         "    夜深了，我坐在窗前，窗外是{place}的夜空，繁星点点。此刻的景色让我不由自主地想起我们一起度过的美好时刻，心中充满了深深的怀念。\n"
         "    我在这里的生活一切都好，只是时常会想起远方的你。每当我在{occasion}时，总会觉得如果你也在这里就好了。我想告诉你，{message}。\n"
         "    虽然我们相隔千山万水，但在我心中，你就像是星光一样，遥远却又温暖而亮堂。我知道我们各自的生活都很忙碌，但我仍期盼着我们能找到机会，重新相聚，在{future_place}再次开启我们的故事。\n"
         "    我会在那里等你，就像星星等待太阳的光芒一样，静候我们的重逢。\n\n"
         "    请照顾好自己，保持快乐和健康，因为你的快乐对我来说就是最大的安慰。\n\n"
         "    此致\n"
         "    敬礼，\n"
         "{sender_name}\n"
         "{date}\n"),

        ("尊敬的{title} {last_name}，\n\n"
         "    时光如梭，转眼间已是{season}的季节。自从我们上一次就{topic}交换了意见之后，我一直沉浸在那次讨论中产生的种种思考。您对于{field}的深刻见解令我受益匪浅，这也让我不断地在专业领域内进一步钻研和探索。\n"
         "    基于我们之前的讨论，我有一些新的想法和提案，这些可能对我们的合作项目大有裨益。我认为通过进一步的沟通，我们可以将这些想法转化为实际的行动计划，并且对相关行业产生深远的影响。\n"
         "    如果您的日程允许，我希望在近期内我们能够再度会面，或是通过视频会议的方式进行深入交流。我相信，通过我们的共同努力，可以推动{project_name}达到一个新的水平。\n\n"
         "    请在您方便的时候回复我，期待与您的再次合作，并再次感谢您之前给予我的宝贵时间与意见。\n\n"
         "    祝您工作顺利，个人愉快。\n\n"
         "    真诚的，\n"
         "{sender_name}\n"
         "{date}\n")
    ]
    return random.choice(letters)


