def generate_poem():
    """ 生成诗歌模板 """
    poems = [
        ("晚风轻拂山峰，\n月光洒满青石。\n思绪飘如过客，\n归心似箭急。"),
        ("晨曦初照花语，\n露珠闪烁微光。\n鸟鸣和风起，\n心随日轮扬。"),
        ("山河遥远路漫漫，\n行人踽踽独前行。\n不畏风雨兼程去，\n只愿岁月静好长。"),
        ("海阔凭鱼跃，\n天高任鸟飞。\n心中有猛虎，\n细嗅蔷薇。"),
        ("碧波轻抚古渡口，\n柳丝轻舞映晚照。\n渔舟唱晚归人稀，\n天边孤鹭舞翩跹。"),
        ("古道西风瘦马行，\n黄昏独立思无穷。\n万里孤云何处去，\n一江明月待君共。"),
        ("竹影摇曳幽径静，\n石桥横跨细溪流。\n问君此去何所求，\n心随山水自逍遥。"),
        ("霜叶红于二月花，\n林间沐露叶扬花。\n晨光初照露成珠，\n倚窗凝思忆流年。"),
        ("春风得意马蹄疾，\n一日看尽长安花。\n无限江山梦中行，\n故人相望若为远。"),
    ]
    return random.choice(poems)



def extract_content(pattern, text):
    """ 从文本中提取特定模式的内容 """
    match = re.search(pattern, text)
    if match:
        return match.group(1).strip()
    return None

def special_question_handler(input_text):
    """处理特定的问题模式"""

    match = re.search(r"你最喜欢(哪个|什么)([^，。？!]+)", input_text)
    if match:
        item = match.group(2).strip()  # 获取“哪个”或“什么”后面的内容
        replies = [
            f"我没有最喜欢的{item}。",
            f"作为一个语言模型，我没有喜欢的{item}。",
            f"我不像人类一样有情感和思维，所以我并没有最喜欢的{item}。",
            f"我并没有最喜欢的{item}，因为我没有像人类一样的爱好。"
        ]
        return random.choice(replies)

    # 处理“我叫...”的情况
    match = re.search(r"(我叫|我的名字叫|叫我|我的名字是|你可以叫我)([^，。？!]+)", input_text)
    if match:
        name = match.group(2).strip()
        replies = [
            f"很高兴认识你，{name}！",
            f"你好{name}，很高兴和你交流。",
            f"好的，{name}，很高兴见到你。",
            f"好的{name}，请问有什么可以帮到你的吗？",
            f"你好，{name}，有什么想聊的吗？",
            f"{name}，这是一个好名字，很高兴认识你，有什么需要帮助的吗？"
        ]
        return random.choice(replies)
    
    if "你对" in input_text and ("怎么看" in input_text or "怎样看" in input_text):
        content = extract_content(r"你对(.+?)怎么看", input_text) or extract_content(r"你对(.+?)怎样看", input_text)
        if content:
            return random.choice([f"我对{content}没什么特别看法。", f"关于{content}，我没有具体的观点。"])

    if "你和" in input_text and ("谁厉害" in input_text or "谁更强" in input_text):
        content = extract_content(r"你和(.+?)(谁厉害|谁更强)", input_text)
        if content:
            return random.choice([f"当然是{content}更厉害了，我只是一个聊天机器人。", f"我无法与{content}相比，但我会尽力提供帮助。"])

    if re.search(r"你(有没有|)看过(.+?)(吗|)", input_text):
        content = extract_content(r"你(有没有|)看过(.+?)(吗|)", input_text)
        if content:
            return random.choice([
                f"我没看过{content}。",
                f"作为一个聊天机器人，我不观看任何内容。",
                f"关于{content}，我可以提供一些信息。"
            ])
    
    if re.search(r"写[两2三3四4五5六6七7八8九9]|生成[两2三3四4五5六6七7八8九9]", input_text):
        replies = [
            "不好意思，以我目前的能力，并不能为你生成多份内容。请谅解。",
            "抱歉，以我目前的能力，一次只能生成一份内容。",
            "我一次只能生成一份内容，你让我生成一份就可以了。",
            "我现在只能生成一份内容，这是为了减少算力需求和时间。谢谢您的理解。"
        ]
        return random.choice(replies)

    # 合并处理“你会...语吗”和“你对...怎么看”的情况
    if re.search(r"你会(.+?)语吗", input_text):
        language = extract_content(r"你会(.+?)语吗", input_text)
        if language:
            return random.choice([
                f"我是一个中文的语言模型，不会{language}语。",
                f"不好意思，我不会{language}语。"
            ])
    elif re.search(r"你对(.+?)(怎么看|怎样看)", input_text):
        content = extract_content(r"你对(.+?)(怎么看|怎样看)", input_text)
        if content:
            return random.choice([
                f"我对{content}没什么特别看法。",
                f"关于{content}，我没有具体的观点。"
            ])

    # 处理用户询问机器人能否制作某物或玩过某游戏的情况
    for pattern, responses in {
        r"你会制作(.+?)吗": [
            "作为一个聊天机器人，我无法制作{item}，但我可以提供相关信息。",
            "我不能直接制作{item}，但我可以尝试帮你找到如何制作它的方法。",
            "制作{item}超出了我的能力，但我可以告诉你更多关于它的信息。"
        ],
        r"你(玩过|有没有玩过)(.+?)吗": [
            "我没有玩过{game}，但我知道一些关于它的信息。",
            "作为一个聊天机器人，我不玩游戏，但我可以提供关于{game}的信息。",
            "玩{game}？这听起来很有趣，但我只能提供相关信息。"
        ]
    }.items():
        match = re.search(pattern, input_text)
        if match:
            content = match.group(1)
            return random.choice([response.format(item=content, game=content) for response in responses])
    
    if "好吃吗" in input_text or "味道怎么样" in input_text:
        food = extract_content(r"(.+)(好吃吗|味道怎么样)", input_text)
        if food:
            return random.choice([f"我也不知道{food}的味道如何。我无法品尝食物。"])

def preprocess_input(input_text):
    # 输入文本的预处理
    if input_text.startswith(("请问","请你","那么","可是","帮我","给我")):
        input_text = input_text[2:] # 移除开头的前两个字
    if input_text.startswith(("我想知道","请告诉我","你能帮我","我想了解")):
        input_text = input_text[4:] # 移除开头的四个字
    if input_text.startswith(("为什么","你知道","什么是")):
        input_text = input_text[3:] # 移除开头的三个字
    if input_text.startswith("请"):
        input_text = input_text[1:] # 移除开头的"请"
    if input_text.endswith(("呢","啊","呀","啦")):
        input_text = input_text[:-1] # 移除结尾的最后一个字
    if input_text.endswith(("怎么办","的意思","怎么样","是什么")):
        input_text = input_text[:-3]
    if input_text.endswith(("是什么意","什么意思","你还没有")):
        input_text = input_text[:-4]
    return input_text


