# 初始化对话历史
dialogue_history = []
last_mentioned_topic = None  # 新增变量，记录最后一次提及的话题

def add_to_dialogue_history(user_input):
    dialogue_history.append(user_input.lower())  # 将用户输入添加到对话历史
    if len(dialogue_history) > 6:  # 保持对话历史的长度
        dialogue_history.pop(0)



def check_for_comforting():
    combined_history = ' '.join(dialogue_history)  # 将对话历史合并成一个字符串进行检查
    latest_input_keywords_matched = False  # 最新输入匹配关键词标志
    topic_flags = {topic: False for topic in topics}  # 初始化话题标志
    
    for topic, details in topics.items():
        keywords_matched = sum(keyword in combined_history for keyword in details['keywords'])
        # 如果累积匹配到足够的关键词，则设置对应话题的标志
        if keywords_matched >= 3:
            topic_flags[topic] = True
            # 检查最新的输入是否包含任何主题关键词
            if any(keyword in dialogue_history[-1] for keyword in details['keywords']):
                latest_input_keywords_matched = True
                # 如果最新输入也匹配到关键词，返回对应的安慰性回复
                if latest_input_keywords_matched:
                    return random.choice(details['responses'])
    
    # 检查用户是否询问了之前提到的话题
    memory_keywords = ["你记得", "我刚刚", "我之前"]
    if any(keyword in user_input for keyword in memory_keywords):
        for topic, flag in topic_flags.items():
            if flag:  # 如果话题标志为True，返回对应的记忆回复
                return f"是的，您之前提到关于您{topic}让您感到很难过。"
    return ""


while True:
    try:
        print("你: ", end="", flush=True)
        user_input = sys.stdin.readline().strip()        
    
        preprocessed_input = preprocess_input(user_input)       
                     
        time.sleep(random.uniform(0.01, 0.03))
        
        add_to_dialogue_history(user_input)

    
        comforting_response = check_for_comforting()
        if comforting_response:
            type_like_human("星星: " + comforting_response)
            continue
        
                     
        trigger_words = ["什么","为什么","吗"]
        if any(word in user_input.strip() for word in trigger_words) and random.random() < 0.6:
            gratitude_response = random.choice([
        "您好，感谢您的提问。",
        "你提出的问题很有趣。",
        "这是个好问题，让我来解答一下。"
            ])
            type_like_human("星星: " + gratitude_response)  # 打印感谢回复                           
                
        # 更新连续短输入历史
        if len(preprocessed_input) < 3:
            short_input_history.append(preprocessed_input)
        else:
            short_input_history.clear()

        if len(short_input_history) >= 3:
            response = random.choice([
                "你为什么要敷衍我？我不愿意继续和你对话了。",
                "这样聊天没有意思，我不想和你对话了。",
                "你的说话方式让我感到不适，你在敷衍我。我不想再和你交流了。"
            ])
            type_like_human(response)  # 使用延迟打印回应
            break
            
        # 使用预处理后的输入进行回应生成
        response = advanced_chatbot(preprocessed_input, corpus)
        
        # 调用 think_like_human 函数来模拟思考过程
        think_like_human()
        
        
        # 检查输入是否与最近的输入高度相似
        if recent_inputs and all(compare_sentence_similarity(user_input, prev_input) > 0.85 for prev_input in recent_inputs[-2:]):
            if len(recent_inputs) >= 3:
                type_like_human("你为什么要这样？我不想再与你对话了。")
                break
            type_like_human("你为什么要发同样的内容？我已经回答过你了。")
            # 清空recent_inputs以避免立即触发重复内容的判断
            recent_inputs = []
            continue

        # 更新最近输入列表
        recent_inputs.append(user_input)
        if len(recent_inputs) > 3:
            recent_inputs.pop(0)
        
        unfriendly_response, should_end_chat = check_unfriendly_content(user_input)
        if unfriendly_response:
            type_like_human("星星: " + unfriendly_response)
            if should_end_chat:
                break  # 结束对话
            else:
                continue
        
        if user_input.lower() in ["退出", "再见", "拜拜"]:
            type_like_human("星星: " + random.choice(goodbye_responses))
            break
       
                            
        # 准备打印聊天机器人的回应
        final_response = "星星: " + response
        
        
        follow_up = ask_follow_up(response)  # 确保传入response参数
        if follow_up:
            final_response += " " + follow_up
            
                
        # 打印最终的回应
        type_like_human(final_response)

    except UnicodeDecodeError as e:
        type_like_human("星星: 输入字符编码错误，请重试。")
        logging.error("字符编码错误: %s", e)
    except ValueError as e:
        type_like_human("星星: 输入值错误，请重新尝试。")
        logging.error("输入值错误: %s", e)
    except FileNotFoundError as e:
        type_like_human("星星: 文件未找到，请检查文件路径。")
        logging.error("文件未找到: %s", e)